import type { DeployPlan } from "@opscrew/plan-schema";
import { MODULE_FILES } from "../generated/modules";
import type { RenderContext, RenderedFile } from "../types";

const OPEN_TO_ALL = ["0.0.0.0/0", "::/0"];

const ROOT_HEADER = [
  "# Generated by OpsCrew from opscrew/plan.yaml. You own this code, but `opscrew provision`",
  "# regenerates this file; change the plan (or the vendored modules) instead.",
].join("\n");

/** Directory of the vendored modules, next to the root module directory. */
export function modulesDirFor(infraDir: string): string {
  const parts = infraDir.replace(/\\/g, "/").replace(/\/+$/, "").split("/");
  parts.pop();
  return [...parts, "modules"].join("/");
}

function usesCloudflare(plan: DeployPlan): boolean {
  return plan.dns.provider === "cloudflare" && plan.dns.domain !== undefined;
}

/** CIDRs allowed to reach ports 80/443: Cloudflare's ranges when proxied and restricted. */
export function httpAllowedCidrs(plan: DeployPlan, ctx: RenderContext): string[] {
  const ranges = ctx.cloudflare?.ipRanges;
  if (
    usesCloudflare(plan) &&
    plan.dns.proxied &&
    plan.security.httpAllowedFrom === "cloudflare" &&
    ranges
  ) {
    const all = [...ranges.ipv4, ...ranges.ipv6];
    if (all.length > 0) return all;
  }
  return OPEN_TO_ALL;
}

function versionsTf(plan: DeployPlan): string {
  const providers = [
    "    hcloud = {",
    '      source  = "hetznercloud/hcloud"',
    '      version = "~> 1.70"',
    "    }",
  ];
  if (usesCloudflare(plan)) {
    providers.push(
      "    cloudflare = {",
      '      source  = "cloudflare/cloudflare"',
      '      version = "~> 5.27"',
      "    }",
    );
  }
  return [
    ROOT_HEADER,
    "",
    "terraform {",
    '  required_version = ">= 1.6.0"',
    "",
    "  required_providers {",
    ...providers,
    "  }",
    "",
    "  # State lives outside the repository; OpsCrew passes the path with -backend-config at init.",
    '  backend "local" {}',
    "}",
    "",
  ].join("\n");
}

function mainTf(plan: DeployPlan): string {
  const lines = [
    ROOT_HEADER,
    "",
    "# Token from the HCLOUD_TOKEN environment variable (never stored in files or state).",
    'provider "hcloud" {}',
    "",
  ];
  if (usesCloudflare(plan)) {
    lines.push(
      "# Token from the CLOUDFLARE_API_TOKEN environment variable.",
      'provider "cloudflare" {}',
      "",
    );
  }
  lines.push(
    'module "server" {',
    '  source = "../modules/hetzner-vps"',
    "",
    "  name               = var.app_name",
    "  location           = var.location",
    "  server_type        = var.server_type",
    "  image              = var.image",
    "  backups            = var.backups",
    "  ssh_public_key     = var.deploy_ssh_public_key",
    "  ssh_allowed_cidrs  = var.ssh_allowed_cidrs",
    "  http_allowed_cidrs = var.http_allowed_cidrs",
    '  labels             = { "managed-by" = "opscrew", app = var.app_name }',
    "}",
    "",
  );
  if (usesCloudflare(plan)) {
    lines.push(
      'module "dns" {',
      '  source = "../modules/cloudflare-dns"',
      "",
      "  zone_id            = var.cloudflare_zone_id",
      "  domain             = var.domain",
      "  ipv4               = module.server.ipv4_address",
      "  ipv6               = module.server.ipv6_address",
      "  proxied            = var.proxied",
      "  www                = var.www",
      "  manage_config_rule = var.manage_config_rule",
      "  manage_waf_rules   = var.manage_waf_rules",
      "}",
      "",
    );
  }
  return lines.join("\n");
}

interface VariableSpec {
  name: string;
  type: string;
  description: string;
}

function variables(plan: DeployPlan): VariableSpec[] {
  const base: VariableSpec[] = [
    { name: "app_name", type: "string", description: "App name, used for resource names." },
    { name: "location", type: "string", description: "Hetzner Cloud location." },
    { name: "server_type", type: "string", description: "Hetzner Cloud server type." },
    { name: "image", type: "string", description: "Operating system image." },
    { name: "backups", type: "bool", description: "Hetzner automated backups." },
    {
      name: "deploy_ssh_public_key",
      type: "string",
      description: "Public half of the deploy key.",
    },
    {
      name: "ssh_allowed_cidrs",
      type: "list(string)",
      description: "Networks allowed to reach SSH.",
    },
    {
      name: "http_allowed_cidrs",
      type: "list(string)",
      description: "Networks allowed to reach ports 80 and 443.",
    },
  ];
  if (!usesCloudflare(plan)) return base;
  return [
    ...base,
    { name: "domain", type: "string", description: "Hostname of the app." },
    { name: "cloudflare_zone_id", type: "string", description: "Cloudflare zone id." },
    { name: "proxied", type: "bool", description: "Proxy traffic through Cloudflare." },
    { name: "www", type: "bool", description: "Also serve www.<domain>." },
    { name: "manage_config_rule", type: "bool", description: "Manage the TLS configuration rule." },
    { name: "manage_waf_rules", type: "bool", description: "Manage the WAF custom rule." },
  ];
}

function variablesTf(plan: DeployPlan): string {
  const blocks = variables(plan).map((v) =>
    [
      `variable "${v.name}" {`,
      `  description = ${JSON.stringify(v.description)}`,
      `  type        = ${v.type}`,
      "}",
    ].join("\n"),
  );
  return `${ROOT_HEADER}\n\n${blocks.join("\n\n")}\n`;
}

function outputsTf(plan: DeployPlan): string {
  // biome-ignore lint/suspicious/noTemplateCurlyInString: HCL interpolation, not JavaScript.
  const url = usesCloudflare(plan) ? "module.dns.url" : '"http://${module.server.ipv4_address}"';
  return [
    ROOT_HEADER,
    "",
    'output "server_ipv4" {',
    "  value = module.server.ipv4_address",
    "}",
    "",
    'output "server_ipv6" {',
    "  value = module.server.ipv6_address",
    "}",
    "",
    'output "server_id" {',
    "  value = module.server.server_id",
    "}",
    "",
    'output "server_name" {',
    "  value = module.server.server_name",
    "}",
    "",
    'output "url" {',
    `  value = ${url}`,
    "}",
    "",
  ].join("\n");
}

/** Non-secret variable values, written as `terraform.tfvars.json`. */
export function tfvars(plan: DeployPlan, ctx: RenderContext): Record<string, unknown> {
  const values: Record<string, unknown> = {
    app_name: plan.app.name,
    location: plan.target.location,
    server_type: plan.target.serverType,
    image: plan.target.image,
    backups: plan.target.backups,
    deploy_ssh_public_key: ctx.deploySshPublicKey.trim(),
    ssh_allowed_cidrs: plan.security.sshAllowedCidrs,
    http_allowed_cidrs: httpAllowedCidrs(plan, ctx),
  };
  if (usesCloudflare(plan)) {
    values.domain = plan.dns.domain;
    values.cloudflare_zone_id = ctx.cloudflare?.zoneId ?? "";
    values.proxied = plan.dns.proxied;
    values.www = plan.dns.www;
    values.manage_config_rule = ctx.cloudflare?.manageConfigRule ?? false;
    values.manage_waf_rules =
      (ctx.cloudflare?.manageWafRules ?? false) && plan.security.wafCustomRules;
  }
  return values;
}

/**
 * The root module (`versions.tf`, `main.tf`, `variables.tf`, `outputs.tf`,
 * `terraform.tfvars.json`) under `plan.infra.dir`, plus vendored copies of the modules it uses
 * under the sibling `modules/` directory. Deterministic; contains no secrets.
 */
export function renderInfra(plan: DeployPlan, ctx: RenderContext): RenderedFile[] {
  if (usesCloudflare(plan) && !ctx.cloudflare?.zoneId) {
    throw new Error("A Cloudflare zone id is required to render DNS for this plan.");
  }
  const dir = plan.infra.dir.replace(/\\/g, "/").replace(/\/+$/, "");
  const modulesDir = modulesDirFor(dir);
  const files: RenderedFile[] = [
    { path: `${dir}/versions.tf`, content: versionsTf(plan), kind: "infra" },
    { path: `${dir}/main.tf`, content: mainTf(plan), kind: "infra" },
    { path: `${dir}/variables.tf`, content: variablesTf(plan), kind: "infra" },
    { path: `${dir}/outputs.tf`, content: outputsTf(plan), kind: "infra" },
    {
      path: `${dir}/terraform.tfvars.json`,
      content: `${JSON.stringify(tfvars(plan, ctx), null, 2)}\n`,
      kind: "infra",
    },
  ];
  const modules = usesCloudflare(plan) ? ["hetzner-vps", "cloudflare-dns"] : ["hetzner-vps"];
  for (const [path, content] of Object.entries(MODULE_FILES).sort(([a], [b]) =>
    a.localeCompare(b),
  )) {
    if (modules.some((m) => path.startsWith(`${m}/`))) {
      files.push({ path: `${modulesDir}/${path}`, content, kind: "infra" });
    }
  }
  return files;
}
